-- 2026-07-01 — 직원 급여(payroll) DB 저장: staff_payroll (기간별)
-- nik·npwp·no_rek 는 앞자리 0/구분점 보존 위해 text. 급여 항목은 numeric(IDR).
create table if not exists public.staff_payroll (
  nik                     text not null,
  npwp                    text,
  no_rek                  text,
  kode_ter                text,
  ter_pct                 numeric,
  gaji_pokok              numeric,
  tunj_jabatan            numeric,
  total_tunj_tetap        numeric,
  total_tunj_tidak_tetap  numeric,
  total_bpjs_perusahaan   numeric,
  total_gaji_gross        numeric,
  total_potongan          numeric,
  take_home_pay           numeric,
  periode                 text not null,
  created_at              timestamptz not null default now(),
  primary key (nik, periode)
);

alter table public.staff_payroll enable row level security;
drop policy if exists "staff_payroll read authenticated" on public.staff_payroll;
create policy "staff_payroll read authenticated"
  on public.staff_payroll for select to authenticated using (true);

create index if not exists staff_payroll_periode_idx on public.staff_payroll (periode desc);

on conflict (nik, periode) do nothing;
